contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    // single public test function: take an unused input to vary the execution
    function run(uint256 dummy) public payable {
        require(true);
        // observe C's balance before the call
        uint256 beforeBal = address(c).balance;
        // perform the call and record whether it reverted
        bool reverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        // After the call: either it reverted, or C's balance is zero.
        assert(reverted || address(c).balance == 0 || beforeBal == 0);
    }
    receive() external payable {}
}

